//! HTML shell for pages generated by the server itself (directory listing,
//! default error pages, upload result). The stylesheet is embedded at compile
//! time, so these pages look right regardless of any route's `root`.

pub const STYLE: &str = include_str!("../www/style.css");

/// `title` and `inner` must already be HTML-escaped.
pub fn page(title: &str, inner: &str) -> String {
    format!(
        "<!DOCTYPE html><html lang=\"ru\"><head><meta charset=\"utf-8\">\
         <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\
         <title>{title}</title><style>{style}</style></head><body>\
         <div class=\"blob blob-1\"></div><div class=\"blob blob-2\"></div>\
         <main class=\"container\">{inner}</main></body></html>\n",
        title = title,
        style = STYLE,
        inner = inner
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn page_embeds_style_and_content() {
        let p = page("T", "<p>hello</p>");
        assert!(p.contains("<title>T</title>"));
        assert!(p.contains("<p>hello</p>"));
        assert!(p.contains(".container"));
    }
}
